export interface JurisdictionOption {
  id: 'IN' | 'NP' | 'US' | 'GB' | 'GLOBAL';
  name: string;
  flag: string;
  subTitle: string;
}

export const AVAILABLE_JURISDICTIONS: JurisdictionOption[] = [
  { id: 'IN', name: 'India', flag: '🇮🇳', subTitle: 'Constitution, BNS, BNSS, BSA, CPC' },
  { id: 'NP', name: 'Nepal', flag: '🇳🇵', subTitle: 'Constitution 2072, Muluki Codes' },
  { id: 'US', name: 'United States', flag: '🇺🇸', subTitle: 'US Constitution, Title 18, UCC' },
  { id: 'GB', name: 'United Kingdom', flag: '🇬🇧', subTitle: 'UK Public Law, English Contract' },
  { id: 'GLOBAL', name: 'International', flag: '🌐', subTitle: 'UN Charter, UDHR, Human Rights' },
];

export const getBooksForJurisdiction = (countryOrCode?: string): BookNode[] => {
  const norm = (countryOrCode || '').toLowerCase().trim();
  if (norm === 'nepal' || norm === 'np') return NEPAL_LEGAL_BOOKS_DATABASE;
  if (norm === 'us' || norm === 'usa' || norm === 'united states' || norm === 'america') return US_LEGAL_BOOKS_DATABASE;
  if (norm === 'uk' || norm === 'gb' || norm === 'united kingdom' || norm === 'england' || norm === 'britain') return UK_LEGAL_BOOKS_DATABASE;
  if (norm === 'global' || norm === 'international' || norm === 'un') return GLOBAL_LEGAL_BOOKS_DATABASE;
  return ALL_LEGAL_BOOKS_DATABASE; // Default India
};
